{ "explanation": "Area is a product of two lengths: for a triangle, A = ½·base·height. When you scale the triangle by k, *both* the base and the height get multiplied by k, so the new area is ½·(kb)·(kh) = k²·(½bh) = k²·A₀ — the factor k shows up once for each of the two dimensions. This is true for every shape: lengths scale by k, areas by k² (and volumes by k³). Use the slider to scale the triangle and drag the yellow apex to reshape it — the area always tracks k² times the original, which the unit grid lets you verify by counting squares.", "manimCode": "// Title
const title = new Text({ text: 'Scaling a triangle by k multiplies its area by k²', fontSize: 26, color: WHITE });
title.moveTo([0, 3.55, 0]);

// Faint unit grid: each square = 1 unit of area
const gridLines = [];
for (let gx = -6; gx <= 6; gx++) {
  const ln = new Line({ start: [gx, -3.4, 0], end: [gx, 3.4, 0], color: GRAY });
  ln.setOpacity(0.15);
  ln.setStrokeWidth(1);
  gridLines.push(ln);
  scene.add(ln);
}
for (let gy = -3; gy <= 3; gy++) {
  const ln = new Line({ start: [-6.5, gy, 0], end: [6.5, gy, 0], color: GRAY });
  ln.setOpacity(0.15);
  ln.setStrokeWidth(1);
  gridLines.push(ln);
  scene.add(ln);
}

// Triangle defined relative to pivot (midpoint of base), so scaling keeps base centered
const pivot = [-1.5, -1.5, 0];
let k = 1;
const A_rel = [-1.5, 0, 0];   // base half-width 1.5  =>  b = 3
const B_rel = [1.5, 0, 0];
const C_rel = [0, 2.5, 0];    // apex, h = 2.5 (draggable)

function wp(rel, kk) {
  return [pivot[0] + kk * rel[0], pivot[1] + kk * rel[1], 0];
}

// Ghost = original triangle (k = 1)
const ghost = new Polygon({ vertices: [wp(A_rel, 1), wp(B_rel, 1), wp(C_rel, 1)], color: GRAY });
ghost.setFillOpacity(0);
ghost.setStrokeWidth(2);

// Scaled triangle
const tri = new Polygon({ vertices: [wp(A_rel, 1), wp(B_rel, 1), wp(C_rel, 1)], color: BLUE });
tri.setFill(BLUE, 0.3);
tri.setStrokeWidth(3);

// Height segment + right-angle marker
const C0 = wp(C_rel, 1);
const heightSeg = new Polygon({ vertices: [C0, [C0[0], pivot[1], 0]], color: GREEN });
heightSeg.setFillOpacity(0);
heightSeg.setStrokeWidth(2);
const m0 = 0.15;
const marker = new Polygon({ vertices: [
  [C0[0], pivot[1], 0], [C0[0] + m0, pivot[1], 0],
  [C0[0] + m0, pivot[1] + m0, 0], [C0[0], pivot[1] + m0, 0]
], color: WHITE });
marker.setFillOpacity(0);
marker.setStrokeWidth(1.5);

// Draggable apex
const dot = new Dot({ point: C0, color: YELLOW });

function makeLabel(str, pos, size, color) {
  const t = new Text({ text: str, fontSize: size, color: color });
  t.moveTo(pos);
  return t;
}
function swapLabel(oldT, str, pos, size, color) {
  scene.remove(oldT);
  const nt = makeLabel(str, pos, size, color);
  scene.add(nt);
  return nt;
}

// Initial labels
let kbLabel = makeLabel('kb = 3.0', [pivot[0], -2.0, 0], 22, BLUE);
let khLabel = makeLabel('kh = 2.5', [C0[0] + 0.62, (C0[1] + pivot[1]) / 2, 0], 22, GREEN);
let kText = makeLabel('k = 1.00', [3.2, 1.5, 0], 26, YELLOW);
let ratioText = makeLabel('Area ratio = k² = 1.00', [3.2, 0.75, 0], 24, WHITE);
let areaText = makeLabel('A = 3.75 · k² = 3.75', [3.2, 0.05, 0], 24, WHITE);
const hint = makeLabel('drag the yellow dot to reshape the triangle', [-1.5, -2.55, 0], 18, GRAY);
const caption = makeLabel('gray outline = original (k = 1), each grid square = 1 unit²', [-1.5, -3.05, 0], 18, GRAY);

function refresh() {
  const A = wp(A_rel, k), B = wp(B_rel, k), C = wp(C_rel, k);
  tri.setVertices([A, B, C]);
  ghost.setVertices([wp(A_rel, 1), wp(B_rel, 1), wp(C_rel, 1)]);
  const foot = [C[0], pivot[1], 0];
  heightSeg.setVertices([C, foot]);
  const m = 0.15;
  marker.setVertices([
    [foot[0], foot[1], 0], [foot[0] + m, foot[1], 0],
    [foot[0] + m, foot[1] + m, 0], [foot[0], foot[1] + m, 0]
  ]);
  const b = 3, h = C_rel[1];
  const A0 = 0.5 * b * h;
  const area = A0 * k * k;
  kbLabel = swapLabel(kbLabel, 'kb = ' + (b * k).toFixed(1), [pivot[0], -2.0, 0], 22, BLUE);
  khLabel = swapLabel(khLabel, 'kh = ' + (h * k).toFixed(1), [C[0] + 0.62, (C[1] + pivot[1]) / 2, 0], 22, GREEN);
  kText = swapLabel(kText, 'k = ' + k.toFixed(2), [3.2, 1.5, 0], 26, YELLOW);
  ratioText = swapLabel(ratioText, 'Area ratio = k² = ' + (k * k).toFixed(2), [3.2, 0.75, 0], 24, WHITE);
  areaText = swapLabel(areaText, 'A = ' + A0.toFixed(2) + ' · k² = ' + area.toFixed(2), [3.2, 0.05, 0], 24, WHITE);
}

// Formula: why k² appears
const formula = new MathTex({ latex: 'A = \\frac{1}{2}(kb)(kh) = k^2 \\cdot \\frac{1}{2}bh = k^2 A_0' });
await formula.waitForRender();
formula.scale(0.85);
formula.moveTo([3.1, 2.45, 0]);

// Intro animations
await scene.play(new Write(title));
await scene.play(new Create(ghost));
await scene.play(new FadeIn(tri));
await scene.play(new AnimationGroup([new Create(heightSeg), new Create(marker), new FadeIn(dot)]));
scene.add(kbLabel, khLabel, kText, ratioText, areaText, hint, caption);
await scene.play(new Write(formula));

// Short demo sweep: k from 1 to 1.7 and back
for (let i = 0; i <= 14; i++) {
  k = 1 + i * 0.05;
  dot.moveTo(wp(C_rel, k));
  refresh();
  await scene.wait(0.06);
}
for (let i = 14; i >= 0; i--) {
  k = 1 + i * 0.05;
  dot.moveTo(wp(C_rel, k));
  refresh();
  await scene.wait(0.06);
}
k = 1;
dot.moveTo(wp(C_rel, 1));
refresh();

// Controls
const controls = new Controls(scene, { position: 'bottom-right' });
controls.addSlider({ label: 'scale factor k', min: 0.4, max: 2, value: 1, step: 0.05, onChange: (val) => {
  k = val;
  dot.moveTo(wp(C_rel, k));
  refresh();
}});
controls.addCheckbox({ label: 'show unit grid', checked: true, onChange: (checked) => {
  for (const ln of gridLines) ln.setOpacity(checked ? 0.15 : 0);
}});

// Draggable apex: reshape the triangle, k² law still holds
makeDraggable(dot, scene, {
  constrainX: [-5.2, 2.2],
  constrainY: [-0.6, 3.5],
  onDrag: (mob, pos) => {
    let rx = (pos[0] - pivot[0]) / k;
    let ry = (pos[1] - pivot[1]) / k;
    rx = Math.max(-1.7, Math.min(1.7, rx));
    ry = Math.max(0.6, Math.min(2.5, ry));
    C_rel[0] = rx;
    C_rel[1] = ry;
    mob.moveTo(wp(C_rel, k));
    refresh();
  }
});

await scene.wait(999999);" }

